tool_calls:
awk -F, '
  NR==FNR && FNR>1 { price[$1]=$4; cat[$1]=$3; next }
  FNR>1 { rev[cat[$2]] += $3 * price[$2] }
  END { for (c in rev) print c": "rev[c] }
' /data/products.csv /data/orders.csv | sort -t: -k2 -nr

